mapper.select:
SELECT * FROM exam_questions
WHERE exam_id = #{examId}
ORDER BY question_number

mapper.update:
UPDATE exam_questions
SET section_id = #{sectionId}, question_number = #{questionNumber}, question_type = #{questionType}, large_category = #{largeCategory}, small_category = #{smallCategory}, score = #{score}, correct_answer = #{correctAnswer}, question_text = #{questionText}, passage = #{passage}, sort_order = #{sortOrder}
WHERE question_id = #{questionId}
